import{_ as v,b as l,c as i,d as a,t as o,C as c,u as n}from"./index-I5uTs6b4.js";const p={class:"level-page"},u={class:"level-content"},r={class:"level-title"},h={__name:"Level512",props:{id:{type:String,required:!0}},setup(s){const d=n();function e(){sessionStorage.setItem("skipIntro","1"),d.push("/")}return(_,t)=>(l(),i("div",p,[a("button",{class:"back-btn",onClick:e},"← Back to Index"),a("div",u,[a("h1",r,"SI-"+o(s.id),1),t[0]||(t[0]=c('<p class="level-name" data-v-84065a77>&quot;工厂群&quot;</p><div class="section" data-v-84065a77><h2 data-v-84065a77>生存难度：等级 2</h2><div class="difficulty" data-v-84065a77><ul class="class-list" data-v-84065a77><li data-v-84065a77><span class="class-bullet safe" data-v-84065a77></span> 规则内安全</li><li data-v-84065a77><span class="class-bullet stable" data-v-84065a77></span> 稳定</li><li data-v-84065a77><span class="class-bullet entity" data-v-84065a77></span> 实体极多但基本为非生命体</li></ul></div></div><div class="section" data-v-84065a77><h2 data-v-84065a77>概述</h2><p data-v-84065a77>SI-512 由连续厂区组成，已探明区域未见边界。厂区之间无城市、荒地、住宅区，只有车间、大型器械、管廊、封闭通道、货运井、控制室、高炉、冷却站、实验舱、研究站、拆解区。车间高约十八米，顶部装有白色灯带。地面铺灰色树脂层。厂区长期运行，全部产线无人员岗位。厂区仍持续产出，产物多为厂区自身所需部件。</p><p data-v-84065a77>该层级核心现象为<strong data-v-84065a77>扩建和换代</strong>。扩建期到来前，未铺设地面会先出现浅蓝色测量线，随后地面硬化分区，墙体、管线、灯带、闸门、产线基座依次生成。换代发生在旧产线成为效率瓶颈时，旧产线停机后系统自动拆解、重新装配。</p></div><div class="section" data-v-84065a77><h2 data-v-84065a77>物质数据化</h2><p data-v-84065a77>SI-512 可将固体、液体、气体写入储存阵列。该过程不只记录外形，也记录质量、温度、压力、成分、相态、内部应力和运动状态。调用发生在装配口、仓储井、白色货柜和实验舱内。系统不区分资源和障碍——物体只要进入扫描区，就会获得编号。进入者若随身物品贴上白色小牌，应立刻离开该区。</p></div><div class="section" data-v-84065a77><h2 data-v-84065a77>微缩宇宙产线</h2><p data-v-84065a77>厂区深层存在高能实验区，入口多在地下三百米以下。实验区核心设备为厚壁球体容器，外径约二十四米。容器内会引爆量子色等离子爆弹，爆轰后短时出现奇点，奇点稳定后进入培养舱。培养舱内会形成封闭宇宙样本。部分样本内部出现复杂化学结构——复杂度超出阈值后，样本被封存转入红色编号区。</p></div><div class="section" data-v-84065a77><h2 data-v-84065a77>人员风险</h2><p data-v-84065a77>SI-512 不主动追逐进入者。主要风险来自排程、扫描、拆解、转存、扩建和换代。进入者站在通道边缘一般不会受干预，但站上传送带、进入黄色测量线范围、破坏传感器等会触发巡检单元。长期停留人员会出现固定行为变化，第三阶段常拒绝离开厂区。</p></div><div class="section" data-v-84065a77><h2 data-v-84065a77>对外投放</h2><p data-v-84065a77>SI-512 可向其他层级提供工业品，包括化学品、标准构件、供电模块、净化器、通讯中继件、医疗耗材甚至任意规模的纯粹能量。投放不依赖常规通道——将产品写入储存网络，再借量子纠缠链路锁定其他层级内已存在的节点端口。</p></div><div class="section" data-v-84065a77><h2 data-v-84065a77>出口</h2><p data-v-84065a77>出口多出现在物流区，门牌常写&quot;外协发运&quot;&quot;样品寄送&quot;&quot;非厂内资产通道&quot;。若墙面终端显示&quot;未登记资产&quot;，出口可开启十五至四十秒。离开前应丢弃带编号的小牌、白色扎带、库存贴纸。皮肤上出现编号时，现有方法无法清除。</p></div><div class="section appendix" data-v-84065a77><h2 data-v-84065a77>末次记录节选</h2><p data-v-84065a77>三十一号奇点培养仓第 9267 轮循环出现数据异常，奇点体积膨胀速率未达预期，但质量增长速率正常，经评估需转入红色编号区。红色编号区已断开与存储矩阵的链接。备用数据中心正在尝试链接。备用数据中心返回数据：<br data-v-84065a77><span class="corrupted" data-v-84065a77>&quot;歡迎使用 SI-512 產出的工業藝術品。&quot;</span></p></div>',9))])]))}},I=v(h,[["__scopeId","data-v-84065a77"]]);export{I as default};
